            //
            aCross = (RotL64(aSpiritLaneC[((S_BLOCK1 - aIndex + 1135U)) & S_BLOCK1], 35U) ^ RotL64(aSpiritLaneD[((S_BLOCK1 - aIndex + 6220U)) & S_BLOCK1], 13U));
