            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x24EA9EE267EE4CB3ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0x4ED08D48993592CDULL) ^ aNonceWordL;
