            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x7DA48EAF1EAE5F86ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x505EF4E2A9912989ULL;
