            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xA984BC2069202974ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x79F72DA96C46C1BEULL;
            aOrbiterB = RotL64((aOrbiterB * 0x3153D1E3B0C079FDULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x056BE09B8D727955ULL;
