            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0x0962A6B5BCC1DFD8ULL) + aOUSaltG[(((511U - aIndex) + 349U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0x3AF434B701A1AFC7ULL) ^ aOUSaltD[(((511U - aIndex) + 21U)) & S_SALT1];
