            //
            aWandererI = aWandererI + ((((RotL64(aScatter, 53U) + aOrbiterB) + RotL64(aOrbiterK, 11U)) + aNonceWordE) + aWUSaltB[(((511U - aIndex) + 109U)) & S_SALT1]);
