            aWandererH = aWandererH ^ (((RotL64(aIngress, 21U) + aOrbiterA) + RotL64(aOrbiterJ, 51U)) + aNonceWordK);
            aWandererJ = aWandererJ + ((RotL64(aScatter, 23U) + aOrbiterE) + RotL64(aOrbiterC, 53U));
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 3U) + aOrbiterG) + RotL64(aOrbiterF, 18U));
            aWandererG = aWandererG + ((((RotL64(aCross, 48U) + aOrbiterI) + RotL64(aOrbiterB, 41U)) + aNonceWordN) + aWUSaltH[(((511U - aIndex) + 343U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererH, 34U));
            aCarry = aCarry + (RotL64(aWandererK, 51U) ^ aWandererD);
            aCarry = aCarry + (RotL64(aWandererB, 39U) ^ aWandererI);
