            aWandererE = aWandererE + ((((RotL64(aScatter, 23U) + aOrbiterJ) + RotL64(aOrbiterD, 3U)) + aNonceWordJ) + aWUSaltB[(((511U - aIndex) + 9U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererK, 5U) ^ aWandererI);
