            aWandererB = aWandererB ^ ((((RotL64(aScatter, 5U) + RotL64(aOrbiterH, 43U)) + aOrbiterJ) + aNonceWordA) + aWUSaltH[((aIndex + 261U)) & S_SALT1]);
