            aOrbiterD = (aWandererK + RotL64(aPrevious, 21U)) + 0xE58F792997CBB5E0ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x8F5DA05324BF4B57ULL;
