            aOrbiterH = RotL64((aOrbiterH * 0x6576BB418F2CACD7ULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0xB6B909E67F48C08AULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xA6085B8E926B6BC7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xCABEF0D0633F9265ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x47109CB6B0718F9CULL;
