            aOrbiterJ = RotL64((aOrbiterJ * 0x7B38EEEE67956073ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x9D4323D38B2AB7CBULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0xD27DA98A46D5B9F4ULL) ^ aOUSaltE[(((511U - aIndex) + 151U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x51E3D12183AE0927ULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x41540834A568C5A7ULL;
