            aOrbiterE = RotL64((aOrbiterE * 0xF740FD840A95D883ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0xC7ACA1EEC5E96A3CULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xF1BEC7ECEE1457E9ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xDABDF7F78316EBC7ULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x4D8FA73CF23DEF08ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x769480BF518CCE09ULL;
