            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x73CBF9E4DB97D4B3ULL) + aOUSaltD[((aIndex + 111U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xAD587D365E62D773ULL;
