            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xA3F08C64D555F694ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0xA7868C129FBEDDBFULL) ^ aOUSaltC[(((511U - aIndex) + 160U)) & S_SALT1];
