            aOrbiterK = RotL64((aOrbiterK * 0x6158E8D84F19C639ULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x1AEF0C0E7A0D694FULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0x4232C915894727ACULL) ^ aOUSaltG[((aIndex + 113U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xC22E77C954708487ULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xBE63B7817B8520E7ULL;
