            aWandererD = aWandererD ^ ((((RotL64(aScatter, 43U) + RotL64(aOrbiterE, 5U)) + aOrbiterA) + RotL64(aCarry, 43U)) + aWUSaltE[((aIndex + 264U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aPrevious, 23U) + RotL64(aOrbiterJ, 29U)) + aOrbiterG);
            aWandererF = aWandererF ^ (((RotL64(aCross, 26U) + aOrbiterA) + RotL64(aOrbiterH, 26U)) + aWUSaltD[((aIndex + 420U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererG, 41U));
