            aWandererB = aWandererB + (((RotL64(aPrevious, 21U) + aOrbiterE) + RotL64(aOrbiterJ, 60U)) + aWUSaltH[((aIndex + 449U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aCross, 56U) + aOrbiterC) + RotL64(aOrbiterK, 19U));
