            aWandererC = aWandererC ^ ((RotL64(aScatter, 5U) + aOrbiterA) + RotL64(aOrbiterE, 37U));
            aWandererK = aWandererK + (((RotL64(aPrevious, 11U) + RotL64(aOrbiterD, 3U)) + aOrbiterF) + aWUSaltA[(((511U - aIndex) + 184U)) & S_SALT1]);
            //
